(function (global) {
  var icons = {"off_icon_01": "data:image/png;base64,", "off_icon_02": "data:image/png;base64,", "on_icon_01": "data:image/png;base64,", "on_icon_02": "data:image/png;base64,", "on_icon_03": "data:image/png;base64,", "on_icon_04": "data:image/png;base64,", "on_icon_05": "data:image/png;base64,", "on_icon_06": "data:image/png;base64,", "on_icon_07": "data:image/png;base64,", "on_icon_08": "data:image/png;base64,", "on_icon_09": "data:image/png;base64,", "on_icon_10": "data:image/png;base64,", "on_icon_11": "data:image/png;base64,", "on_icon_12": "data:image/png;base64,", "on_icon_13": "data:image/png;base64,", "on_icon_14": "data:image/png;base64,", "on_icon_15": "data:image/png;base64,", "pack-icon": "data:image/png;base64,"};
  var wallpaper = "data:image/png;base64,";

  function applyIcons(root) {
    var scope = root || document;
    if (!scope.querySelectorAll) return;
    scope.querySelectorAll('[data-nacho-icon]').forEach(function (el) {
      var key = el.getAttribute('data-nacho-icon');
      if (key && icons[key]) {
        if (el.tagName === 'IMG') el.src = icons[key];
        else el.style.backgroundImage = 'url("' + icons[key] + '")';
      }
    });
  }

  function applyWallpaper() {
    if (wallpaper && document.documentElement) {
      document.documentElement.style.setProperty('--nacho-wallpaper', 'url("' + wallpaper + '")');
    }
  }

  function applyAll() {
    applyWallpaper();
    applyIcons(document);
  }

  global.NACHONEKO_ASSETS = {
    icons: icons,
    wallpaper: wallpaper,
    applyIcons: applyIcons,
    applyAll: applyAll
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyAll);
  } else {
    applyAll();
  }
})(typeof window !== 'undefined' ? window : this);
